// Default Year-by-year allocation policies filled from filed data (scripts/yby-allocation-defaults).
// Applied only while a draft's policy is still unselected; any explicit user choice is kept.
import {registerCatalog,localizedText} from './i18n.js';
export const ANNUAL_ALLOCATION_DEFAULTS=Object.freeze({"NFLX": {"patch": {"nflxPolicy": {"policy_label": "Default June 30, 2026 allocation from filed 10-Q claims; judgment inputs from the published restricted illustration", "as_of": "2026-06-30", "operating_cash_reserve": 3000, "debt_value": 14372, "option_volatility": 0.35, "option_remaining_years": 4.5, "option_risk_free_rate": 0.04, "rsu_psu_units_multiplier": 1, "income_tax_claim_reserve": 566, "additional_brazil_claim_excluding_paid_729": 0, "financing_interest_rate_derivative_reserve": 13.574, "financing_fx_derivative_net_claim_reserve": 100, "debt_valuation_basis": "face_principal_excluding_financing_derivatives", "existing_unvested_award_expense_in_ebit_by_year": {"2026": 25, "2027": 25, "2028": 10, "2029": 0, "2030": 0, "2031": 0, "2032": 0, "2033": 0, "2034": 0, "2035": 0}, "existing_award_remaining_expense_assumption": 60, "existing_award_latest_recognition_date": "2028-12-31", "retained_future_grant_cash_compensation_pct_revenue_by_year": {"2026": 0.011, "2027": 0.011, "2028": 0.011, "2029": 0.011, "2030": 0.011, "2031": 0.011, "2032": 0.011, "2033": 0.011, "2034": 0.011, "2035": 0.011, "2036": 0.011}, "retained_other_cash_operating_cost_pct_revenue_by_year": {"2026": 0.2, "2027": 0.2, "2028": 0.2, "2029": 0.2, "2030": 0.2, "2031": 0.2, "2032": 0.2, "2033": 0.2, "2034": 0.2, "2035": 0.2, "2036": 0.2}, "other_claim_reserve": 250, "separate_claim_cash_by_year": {"2026": 929.574, "2027": 0, "2028": 0, "2029": 0, "2030": 0, "2031": 0, "2032": 0, "2033": 0, "2034": 0, "2035": 0}, "accept_cash_fungibility_assumption": true, "accept_operating_lease_and_content_treatment": true, "accept_operating_hedges_embedded_no_separate_asset": true, "accept_existing_award_and_future_sbc_nonoverlap": true, "accept_existing_award_no_unmodeled_positive_cost_additions": true, "accept_source_context_compensation_floor_convention": true, "accept_financing_hedges_separate_and_assumed_closeout": true, "accept_annual_funding_proxy_not_bank_cash": true, "basis": "Filed June 30, 2026 10-Q: cash $9,099.232m + short-term investments $28.678m, senior-note face principal $14,372m (derivatives excluded), separate financing interest-rate derivative net liability $13.574m, 4,163.939676m common shares, 123.891603m vested options at $39.21 weighted strike, 2.012512m unvested RSU/PSU units taken at their reported count (1x). Income-tax reserve $566m is the latest filed gross unrecognized tax benefit (FY2025 10-K; the June 10-Q discloses none). Additional Brazil exposure beyond the $729m paid in H1 is assumed zero; no further amount is disclosed. Operating cash reserve $3,000m, other claims $250m, financing FX reserve $100m, option life 4.5y / volatility 35% / risk-free 4%, existing-award expense $25m/$25m/$10m to Dec 2028, retained 1.1% future-grant and 20% other cash costs, and H2 2026 cash settlement of all separate claims ($929.574m) are the published restricted illustration's analyst choices. Not a current price target."}}, "summary": ["June 30, 2026 allocation using the filed 10-Q cash, $14,372m face debt, rate-hedge liability, shares, options and RSU/PSU count; reserves, option inputs and award-expense schedule follow the published restricted illustration. Not a current price target.", "2026 年 6 月 30 日分配：采用 10-Q 申报的现金、14,372 百万美元面值债务、利率套期负债、股数、期权及 RSU/PSU 数量；各项预留、期权参数和奖励费用计划沿用已发布的受限示例。并非当前目标价。"]}});
export function applyAllocationDefault(d){const x=ANNUAL_ALLOCATION_DEFAULTS[d?.ticker];if(!x)return false;let changed=false;for(const [key,value]of Object.entries(x.patch))if(d[key]==null){d[key]=structuredClone(value);changed=true;}return changed;}
registerCatalog('annualAllocation',{en:Object.fromEntries(Object.entries(ANNUAL_ALLOCATION_DEFAULTS).map(([k,v])=>[k,v.summary[0]])),'zh-Hans':Object.fromEntries(Object.entries(ANNUAL_ALLOCATION_DEFAULTS).map(([k,v])=>[k,v.summary[1]]))});
/** True while the draft still uses the unedited filed-data default. */
export function allocationDefaultActive(d){const x=ANNUAL_ALLOCATION_DEFAULTS[d?.ticker];return !!x&&Object.entries(x.patch).every(([key,value])=>JSON.stringify(d[key])===JSON.stringify(value));}
export function allocationDefaultNoteHTML(ticker){return ANNUAL_ALLOCATION_DEFAULTS[ticker]?`<p>${localizedText('annualAllocation.'+ticker)}</p>`:'';}
